import gc


def make_tree(depth):
    if depth == 0:
        return (None, None)
    return (make_tree(depth - 1), make_tree(depth - 1))


def node_count(depth):
    return (1 << (depth + 1)) - 1


def main():
    n = int(sys.argv[1])
    gc.disable()

    stretch = make_tree(n + 1)
